"""gitignore-style pattern matching. See task.md."""

from __future__ import annotations

import re
from dataclasses import dataclass


class PatternError(ValueError):
    """Raised for a malformed character class or a dangling escape."""


@dataclass(frozen=True)
class _Pattern:
    negated: bool
    dir_only: bool
    anchored: bool
    # None marks a `**` segment; every other entry is a compiled one-segment matcher.
    segments: tuple[re.Pattern[str] | None, ...]


def _strip_trailing_spaces(line: str) -> str:
    end = len(line)
    while end > 0 and line[end - 1] == " ":
        backslashes = 0
        while end - 2 - backslashes >= 0 and line[end - 2 - backslashes] == "\\":
            backslashes += 1
        if backslashes % 2:
            break
        end -= 1
    return line[:end]


def _class_char(seg: str, i: int) -> tuple[str, int]:
    if seg[i] == "\\":
        if i + 1 >= len(seg):
            raise PatternError(f"backslash with nothing after it in {seg!r}")
        return seg[i + 1], i + 2
    return seg[i], i + 1


def _parse_class(seg: str, start: int) -> tuple[str, int]:
    i = start + 1
    negated = i < len(seg) and seg[i] == "!"
    if negated:
        i += 1

    ranges: list[tuple[str, str]] = []
    first = True
    while True:
        if i >= len(seg):
            raise PatternError(f"unclosed character class in {seg!r}")
        if seg[i] == "]" and not first:
            i += 1
            break
        first = False
        lo, i = _class_char(seg, i)
        if i + 1 < len(seg) and seg[i] == "-" and seg[i + 1] != "]":
            hi, i = _class_char(seg, i + 1)
            if hi < lo:
                raise PatternError(f"reversed character range in {seg!r}")
            ranges.append((lo, hi))
        else:
            ranges.append((lo, lo))

    body = "".join(
        f"\\U{ord(lo):08x}-\\U{ord(hi):08x}" if lo != hi else f"\\U{ord(lo):08x}"
        for lo, hi in ranges
    )
    return f"[{'^' if negated else ''}{body}]", i


def _compile_segment(seg: str) -> re.Pattern[str]:
    parts: list[str] = []
    i = 0
    while i < len(seg):
        c = seg[i]
        if c == "*":
            parts.append(".*")
            i += 1
        elif c == "?":
            parts.append(".")
            i += 1
        elif c == "[":
            fragment, i = _parse_class(seg, i)
            parts.append(fragment)
        elif c == "\\":
            literal, i = _class_char(seg, i)
            parts.append(re.escape(literal))
        else:
            parts.append(re.escape(c))
            i += 1
    return re.compile("".join(parts), re.DOTALL)


def _compile_line(line: str) -> _Pattern | None:
    line = _strip_trailing_spaces(line)
    if not line or line.startswith("#"):
        return None

    negated = line.startswith("!")
    if negated:
        line = line[1:]

    dir_only = line.endswith("/")
    if dir_only:
        line = line[:-1]

    if not line:
        return None

    anchored = "/" in line
    if anchored and line.startswith("/"):
        line = line[1:]

    texts = line.split("/")
    segments = tuple(
        None if len(texts) > 1 and text == "**" else _compile_segment(text)
        for text in texts
    )
    return _Pattern(negated, dir_only, anchored, segments)


def _match_segments(segments: tuple[re.Pattern[str] | None, ...], parts: list[str]) -> bool:
    count = len(parts)
    positions = {0}
    for index, segment in enumerate(segments):
        if segment is None:
            low = 1 if index == len(segments) - 1 else 0
            positions = {q for p in positions for q in range(p + low, count + 1)}
        else:
            positions = {p + 1 for p in positions if p < count and segment.fullmatch(parts[p])}
        if not positions:
            return False
    return count in positions


def _matches(pattern: _Pattern, parts: list[str], is_dir: bool) -> bool:
    if pattern.dir_only and not is_dir:
        return False
    if not pattern.anchored:
        return pattern.segments[0].fullmatch(parts[-1]) is not None
    return _match_segments(pattern.segments, parts)


def is_ignored(patterns: list[str], path: str, is_dir: bool) -> bool:
    """Return True when `path` is ignored by `patterns`."""
    compiled = [p for p in (_compile_line(line) for line in patterns) if p is not None]
    parts = path.split("/")
    ignored = False
    for pattern in compiled:
        if _matches(pattern, parts, is_dir):
            ignored = not pattern.negated
    return ignored
